/* ---- film 121 helpers ---- */
function ell121(cx, cy, rx, ry, col, a, lw = 1.5, dash = 0) {
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = lw; if (dash) ctx.setLineDash([8, 7]); ctx.beginPath();
  ctx.ellipse(cx, cy, Math.max(rx, 0.1), Math.max(ry, 0.1), 0, 0, Math.PI * 2); ctx.stroke(); ctx.restore();
}
function fillEll121(cx, cy, rx, ry, col, a) {
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a; ctx.fillStyle = col; ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore();
}
function cell121(x, y, w, h, s, col, a, size = 20, fillA = 0.3) { if (a <= 0) return; fillBox(x, y, w, h, col, a * fillA); rect63(x, y, w, h, col, a, 1.6); lblG(s, x + w / 2, y + h / 2 + size * 0.36, C.white, a, size); }
/* population simplex: corner 0 top, 1 bottom-left, 2 bottom-right */
function triPts121(cx, cy, R) { return [[cx, cy - R], [cx - R * 0.866, cy + R * 0.5], [cx + R * 0.866, cy + R * 0.5]]; }
function triMap121(cx, cy, R) { const P = triPts121(cx, cy, R); return (p0, p1, p2) => [p0 * P[0][0] + p1 * P[1][0] + p2 * P[2][0], p0 * P[0][1] + p1 * P[1][1] + p2 * P[2][1]]; }
function tri121(cx, cy, R, a, o = {}) {
  if (a <= 0) return null;
  const P = triPts121(cx, cy, R);
  fillPoly(P, C.cyan, a * 0.07); strokePoly(P, C.cyan, a * 0.75, 2.2);
  const m = triMap121(cx, cy, R);
  if (o.grid) for (let k = 1; k < 4; k++) { const f = k / 4; const A = m(f, 1 - f, 0), B = m(f, 0, 1 - f); dashed(A[0], A[1], B[0], B[1], C.dim, a * 0.35, 1); }
  if (o.labels !== false) { const L = ['|0⟩', '|1⟩', '|2⟩'], off = [[0, -22], [-30, 30], [30, 30]]; P.forEach((p, i) => { dot(p[0], p[1], 11, ['g', 'c', 'm'][i], a); lblG(L[i], p[0] + off[i][0], p[1] + off[i][1], C.white, a, 22); }); }
  if (o.t != null) { const th = o.t * 0.7, p0 = 0.33 + 0.25 * Math.sin(th), p1 = (1 - p0) * (0.5 + 0.4 * Math.sin(th * 1.7 + 1)); const q = m(p0, p1, 1 - p0 - p1); dot(q[0], q[1], 14, 'w', a); ring(q[0], q[1], 22, C.white, a * 0.5, 1.5); }
  return m;
}
function ramp121(f) { f = clamp(f); const s = [[10, 30, 80], [42, 123, 255], [63, 248, 255], [255, 207, 90], [255, 59, 92]]; const x = f * (s.length - 1), i = Math.min(s.length - 2, Math.floor(x)), g = x - i; const c = s[i].map((v, k) => Math.round(v + (s[i + 1][k] - v) * g)); return `rgb(${c[0]},${c[1]},${c[2]})`; }
function axes121(px, py, pw, ph, a, xr, yr, xl, yl) {
  plotAxes(px, py, pw, ph, a, xl, yl);
  return { x: v => px + (v - xr[0]) / (xr[1] - xr[0]) * pw, y: v => py - (v - yr[0]) / (yr[1] - yr[0]) * ph };
}
function series121(pts, xS, yS, col, a, lw = 3, prog = 1) {
  if (a <= 0 || pts.length < 2) return;
  const n = Math.max(2, Math.floor(pts.length * clamp(prog)));
  ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.beginPath();
  for (let i = 0; i < n; i++) { const X = xS(pts[i][0]), Y = yS(pts[i][1]); if (i === 0) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
  ctx.stroke(); ctx.globalAlpha = 1;
}

/* ---- 00 OPEN ---- */
SCENES.open = S => {
  const u = S.u, t = S.t;
  badges(S, ['theory']);
  const s0 = clamp(u / 1.2);
  const hq = Q(S, 0, 'fair chronological channel', 0.6), eq = Q(S, 0, 'history is then erased', 0.8);
  for (let i = 0; i < 8; i++) {
    const q = clamp(hq * 1.6 - i / 10), x = 160 + i * 86, b = rnd(i, 121) > 0.5 ? 1 : 0;
    cell121(x, 250, 70, 56, b ? 'V₁' : 'V₀', b ? C.mag : C.cyan, q * (1 - 0.75 * eq), 22);
    if (eq > 0) line(x + 6, 300, x + 64, 256, C.red, eq * q, 2.5);
  }
  lbl('chronological letters , each with probability 1/2', 470, 340, C.dim, hq * (1 - eq), 16);
  lbl('history erased : no record is output', 470, 340, C.red, eq, 18);
  const m = tri121(370, 560, 150, s0, { t, grid: 1 });
  lbl('unknown qutrit input', 370, 790, C.dim, s0, 16);
  const dq = Q(S, 0, 'only the final qutrit reaches the decoder', 0.6);
  arrow(560, 560, 640, 560, C.gold, dq, 3);
  box(650, 510, 120, 100, C.gold, dq, 2.5, 'rgba(40,30,0,0.45)'); lbl('D', 710, 574, C.gold, dq, 40);
  lbl('terminal decoder', 710, 640, C.gold, dq, 16);
  const items = [['fair chronological channel', 'FAIR CHRONOLOGICAL CHANNEL', 'F = ½ (Ad U₀ + Ad U₁) ,  U₁ = U₀ W', C.cyan], ['history is then erased', 'ERASED HISTORY', 'only the qutrit leaves the channel', C.mag], ['only the final qutrit reaches the decoder', 'TERMINAL DECODER', 'one CPTP map D on the last qutrit', C.gold], ['horizon by horizon', 'EVERY HORIZON', 'n = 0, 1, 2, …  and the limit ∞', C.green]];
  items.forEach(([ph, h, s, col], i) => { const q = Q(S, 0, ph, 0.6); box(930, 215 + i * 150, 860, 125, col, q, 2, 'rgba(0,0,0,0.45)'); lbl(h, 1360, 255 + i * 150, col, q, 21); lblG(s, 1360, 305 + i * 150, C.white, q, 26); });
};

