    const eq = Q(S, 0, 'so its error is exactly two thirds minus q over twelve', 0.6) * f1;
    chip(530, 470, 860, 60, 'e_(−q)(R_fam) = e_(q/2)(id) = 2/3 − q/12', C.white, eq, 24);
